import{_ as e,o as a,a as s,a2 as n}from"./chunks/framework.DCcmcJcL.js";const g=JSON.parse('{"title":"Testing Overview","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/testing.md","filePath":"advanced/testing.md","lastUpdated":1789464754000}'),r={name:"advanced/testing.md"};function i(o,t,d,h,l,c){return a(),s("div",null,t[0]||(t[0]=[n(`<h1 id="testing-overview" tabindex="-1">Testing Overview <a class="header-anchor" href="#testing-overview" aria-label="Permalink to &quot;Testing Overview&quot;">​</a></h1><p>Bagisto has two kinds of automated tests. <strong>Pest tests</strong> check PHP behaviour from inside the application, and <strong>Playwright end-to-end tests</strong> drive a browser through the admin, the storefront and the installer. This page helps you pick one; each has its own page for writing and running it.</p><h2 id="which-tool-for-what" tabindex="-1">Which Tool for What <a class="header-anchor" href="#which-tool-for-what" aria-label="Permalink to &quot;Which Tool for What&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To test</th><th>Write</th><th>Core example</th></tr></thead><tbody><tr><td>A class on its own: a repository, an indexer, a carrier, a tax or DataGrid class, a payment gateway</td><td>A Pest test in the package&#39;s <code>tests/Unit</code></td><td><code>packages/Webkul/Shipping/tests/Unit/CarriersTest.php</code></td></tr><tr><td>What a route does: the page, redirect or JSON it returns, its validation and ACL refusals, and the rows, mail and events behind it</td><td>A Pest test in the package&#39;s <code>tests/Feature</code></td><td><code>packages/Webkul/Admin/tests/Feature/Catalog</code></td></tr><tr><td>A flow a person clicks through in the admin or the storefront: forms, DataGrids, Vue components, cart and checkout</td><td>A Playwright end-to-end test</td><td><code>packages/Webkul/Shop/tests/e2e-pw/tests/checkout</code></td></tr><tr><td>The web installer</td><td>A Playwright end-to-end test</td><td><code>packages/Webkul/Installer/tests/e2e-pw/tests/installer.spec.ts</code></td></tr></tbody></table><p>When a request or a method call can prove the behaviour, write a Pest test: it needs no browser or running server, and it rolls back what it writes. Keep Playwright end-to-end tests for what only a browser shows, such as Vue components, JavaScript and what a person sees on screen.</p><p><a id="test-suites"></a><a id="the-test-database"></a><a id="parallel-runs"></a><a id="running-tests"></a><a id="test-benches"></a><a id="shared-datasets"></a><a id="writing-tests-for-a-package"></a><a id="step-1-create-the-test-case"></a><a id="step-2-autoload-the-test-namespace"></a><a id="step-3-bind-the-test-case"></a><a id="step-4-write-a-test"></a><a id="step-5-add-a-suite"></a><a id="step-6-migrate-and-run-it"></a><a id="things-to-watch"></a><strong>Pest tests:</strong> the suites, the test database, running tests, the test benches and registering a package&#39;s tests are on <a href="./testing-with-pest.html">Testing with Pest</a>.</p><p><a id="end-to-end-tests-with-playwright"></a><a id="running-a-project"></a><a id="configuration"></a><a id="things-to-watch-1"></a><strong>Playwright end-to-end tests:</strong> the three projects, running them, their configuration and writing a spec are on <a href="./testing-with-playwright.html">Testing with Playwright</a>.</p><h2 id="where-the-tests-live" tabindex="-1">Where the Tests Live <a class="header-anchor" href="#where-the-tests-live" aria-label="Permalink to &quot;Where the Tests Live&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tests/</span></span>
<span class="line"><span>├── Pest.php                # binds each package&#39;s tests to its test case</span></span>
<span class="line"><span>├── TestCase.php            # Tests\\TestCase</span></span>
<span class="line"><span>├── Datasets/               # Pest datasets every package can use</span></span>
<span class="line"><span>├── Unit/                   # cross-package Pest tests that need no database</span></span>
<span class="line"><span>└── e2e-pw/helpers/         # helpers shared by the Playwright projects</span></span>
<span class="line"><span></span></span>
<span class="line"><span>packages/Webkul/&lt;Package&gt;/tests/</span></span>
<span class="line"><span>├── &lt;Package&gt;TestCase.php   # the package&#39;s base test case</span></span>
<span class="line"><span>├── Concerns/               # test benches: traits that build fixtures</span></span>
<span class="line"><span>├── Fixtures/               # classes and files the tests load</span></span>
<span class="line"><span>├── Feature/                # Pest feature tests</span></span>
<span class="line"><span>├── Unit/                   # Pest unit tests</span></span>
<span class="line"><span>└── e2e-pw/                 # Admin, Shop and Installer only: the Playwright project</span></span></code></pre></div><h2 id="one-database-one-run-at-a-time" tabindex="-1">One Database, One Run at a Time <a class="header-anchor" href="#one-database-one-run-at-a-time" aria-label="Permalink to &quot;One Database, One Run at a Time&quot;">​</a></h2><p>Neither kind of test brings its own store: the Pest tests and the Admin and Shop specs run against an installed one that already holds data, and the Installer spec against an application that isn&#39;t installed yet.</p><ul><li><strong>Pest tests</strong> use the database in <code>.env</code> and roll back each test; see <a href="./testing-with-pest.html#the-test-database">Testing with Pest</a>.</li><li><strong>Playwright end-to-end tests</strong> drive the store served at <code>APP_URL</code>, so they write to that store&#39;s database and roll back nothing.</li></ul><p>In both, assert on the records the test created, never on counts or the first row of a listing. <strong>Don&#39;t run Pest tests and Playwright end-to-end tests against the same database at the same time.</strong> The specs change settings and prices that the Pest tests read, and the failures look like broken code.</p><h2 id="what-ci-runs" tabindex="-1">What CI Runs <a class="header-anchor" href="#what-ci-runs" aria-label="Permalink to &quot;What CI Runs&quot;">​</a></h2><p>The workflows are in the application&#39;s <code>.github/workflows/</code>:</p><table tabindex="0"><thead><tr><th>Workflow</th><th>Runs on</th><th>What it does</th></tr></thead><tbody><tr><td><code>pest-tests.yml</code></td><td>Every push and pull request</td><td>Installs a fresh store with <code>APP_ENV=testing</code> on PHP 8.4, against MySQL 8.0, MariaDB 10.11 and PostgreSQL 16, then runs <code>vendor/bin/pest</code> in a single process</td></tr><tr><td><code>playwright-tests.yml</code></td><td>A pull request labelled <strong>Need Playwright Testing</strong>, a <code>v*</code> tag, or a manual run</td><td><code>installer_gate</code> runs the Installer spec in English and Arabic on each database. When it passes, <code>playwright_tests</code> installs the store with demo samples and runs Admin and Shop in 10 shards on each database. Both serve the store with nginx and PHP-FPM.</td></tr><tr><td><code>pint-tests.yml</code>, <code>translation-tests.yml</code></td><td>Every push and pull request</td><td><code>pint --test</code> and <code>php artisan bagisto:translations:check</code>; see <a href="./coding-standards.html">Coding Standards</a></td></tr></tbody></table><p>Every Playwright job uploads its HTML report, the per-test results and <code>storage/logs/laravel.log</code> as an artifact kept for one day. The pull request process, including the checks to run before you open one, is in <a href="https://github.com/bagisto/bagisto/blob/master/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a>.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./coding-standards.html">Coding Standards</a>: the conventions a reviewer checks, and the other CI checks.</li><li><a href="./../ai/agent-skills.html">Agent Skills</a>: <code>bagisto-pest-testing</code> and <code>bagisto-playwright-testing</code> carry the full test-writing conventions.</li></ul>`,19)]))}const u=e(r,[["render",i]]);export{g as __pageData,u as default};
